// Generates packages/shared/src/catalog/sheet-features.generated.ts from docs/source/features-by-tier.csv
// (Sheet1 of the client's tier spreadsheet — the source of truth for tiers).
// Run: npm run gen:catalog. A test asserts the generated file is in sync with the CSV.
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const csvPath = resolve(root, 'docs/source/features-by-tier.csv');
const outPath = resolve(root, 'packages/shared/src/catalog/sheet-features.generated.ts');

/** Minimal RFC-4180 CSV parser (handles quoted fields and escaped quotes). */
export function parseCsv(text) {
  const rows = [];
  let row = [];
  let field = '';
  let inQuotes = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"' && text[i + 1] === '"') {
        field += '"';
        i++;
      } else if (c === '"') inQuotes = false;
      else field += c;
    } else if (c === '"') inQuotes = true;
    else if (c === ',') {
      row.push(field);
      field = '';
    } else if (c === '\n' || c === '\r') {
      if (c === '\r' && text[i + 1] === '\n') i++;
      row.push(field);
      field = '';
      if (row.some((f) => f !== '')) rows.push(row);
      row = [];
    } else field += c;
  }
  if (field !== '' || row.length) {
    row.push(field);
    if (row.some((f) => f !== '')) rows.push(row);
  }
  return rows;
}

const TYPE = { Functions: 'function', Reports: 'report', Interface: 'interface' };
// Sheet1 spells one row's module "IP Billing & Cash handling"; it is merged into the canonical name (PLAN.md §1).
const MODULE_ALIASES = { 'IP Billing & Cash handling': 'IP Billing & Cash Handling' };

export function buildRows(csvText) {
  const [header, ...data] = parseCsv(csvText);
  const expected = ['Module', 'Type', 'Function / Report Description', 'Status', 'Status Count', 'Basic', 'Medium', 'Premium'];
  if (JSON.stringify(header) !== JSON.stringify(expected)) throw new Error(`Unexpected CSV header: ${header}`);
  return data.map((r, i) => {
    const [mod, type, name, status, , basic, medium, premium] = r;
    if (!TYPE[type]) throw new Error(`Row ${i + 2}: unknown type "${type}"`);
    for (const v of [basic, medium, premium]) if (v !== 'Y' && v !== 'N') throw new Error(`Row ${i + 2}: tier cell must be Y/N`);
    return {
      row: i + 2,
      sheetModule: MODULE_ALIASES[mod] ?? mod,
      type: TYPE[type],
      name: name.trim(),
      status: status === '' ? null : status,
      basic: basic === 'Y',
      medium: medium === 'Y',
      premium: premium === 'Y',
    };
  });
}

export function render(rows) {
  const lines = rows.map((r) => `  ${JSON.stringify(r)},`).join('\n');
  return `// GENERATED by scripts/gen-catalog.mjs from docs/source/features-by-tier.csv — do not edit by hand.
// Names are copied exactly from Sheet1 (typos included); only surrounding whitespace is trimmed.

export interface SheetRow {
  /** 1-based line number in the CSV (header is line 1). */
  row: number;
  sheetModule: string;
  type: 'function' | 'report' | 'interface';
  name: string;
  status: 'Change' | 'No Change' | 'New' | null;
  basic: boolean;
  medium: boolean;
  premium: boolean;
}

export const SHEET_ROWS: readonly SheetRow[] = [
${lines}
];
`;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const rows = buildRows(readFileSync(csvPath, 'utf8'));
  writeFileSync(outPath, render(rows));
  const count = (k) => rows.filter((r) => r[k]).length;
  console.log(`Wrote ${rows.length} rows (Basic ${count('basic')}, Medium ${count('medium')}, Premium ${count('premium')}) → ${outPath}`);
}
